begin;

create table if not exists public.exercise_physical_objectives (
  id uuid primary key default gen_random_uuid(),
  exercise_id uuid not null references public.exercises(id) on update cascade on delete cascade,
  physical_objective_id uuid not null references public.physical_objectives(id) on update cascade on delete cascade,
  ruolo text not null constraint exercise_physical_objectives_role_check check (ruolo in ('Principale', 'Secondario', 'Complementare')),
  peso integer not null constraint exercise_physical_objectives_weight_check check (peso between 1 and 5),
  motivazione text,
  attivo boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint exercise_physical_objectives_pair_key unique (exercise_id, physical_objective_id)
);

create index if not exists exercise_physical_objectives_exercise_idx
  on public.exercise_physical_objectives (exercise_id, peso desc);
create index if not exists exercise_physical_objectives_physical_idx
  on public.exercise_physical_objectives (physical_objective_id, peso desc)
  where attivo = true;
create unique index if not exists exercise_physical_objectives_one_primary_idx
  on public.exercise_physical_objectives (exercise_id)
  where ruolo = 'Principale';

do $$
begin
  if not exists (
    select 1 from pg_trigger
    where tgname = 'exercise_physical_objectives_set_updated_at'
      and tgrelid = 'public.exercise_physical_objectives'::regclass
  ) then
    create trigger exercise_physical_objectives_set_updated_at
    before update on public.exercise_physical_objectives
    for each row execute function public.set_updated_at();
  end if;
end $$;

alter table public.exercise_physical_objectives enable row level security;
do $$
begin
  if not exists (
    select 1 from pg_policies
    where schemaname = 'public'
      and tablename = 'exercise_physical_objectives'
      and policyname = 'public exercise physical objectives access'
  ) then
    create policy "public exercise physical objectives access"
    on public.exercise_physical_objectives
    for all to anon, authenticated using (true) with check (true);
  end if;
end $$;

