Rapidità piedi","motivazione":"La qualità dei piccoli appoggi condiziona la rapidità di ritorno in guardia.","attivo":true},{"exercise_code":"GK-PRA-036","physical_objective_code":"FIS-023","ruolo":"Secondario","peso":4,"macro_area":"Reattività","obiettivo_fisico":"Reazione multidirezionale","motivazione":"La sequenza richiede reazioni rapide verso soluzioni o direzioni successive.","attivo":true},{"exercise_code":"GK-PRA-037","physical_objective_code":"FIS-021","ruolo":"Principale","peso":5,"macro_area":"Reattività","obiettivo_fisico":"Reazione a stimolo visivo","motivazione":"La risposta è condizionata da uno stimolo visivo trasformato rapidamente in azione.","attivo":true},{"exercise_code":"GK-PRA-037","physical_objective_code":"FIS-012","ruolo":"Secondario","peso":4,"macro_area":"Esplosività","obiettivo_fisico":"Spinta orizzontale","motivazione":"Il movimento richiede produzione rapida di forza sul piano orizzontale/in avanti.","attivo":true},{"exercise_code":"GK-PRA-037","physical_objective_code":"FIS-019","ruolo":"Secondario","peso":4,"macro_area":"Agilità","obiettivo_fisico":"Arresto e ripartenza","motivazione":"La sequenza richiede arresto, recupero posturale e nuova accelerazione.","attivo":true},{"exercise_code":"GK-PRA-037","physical_objective_code":"FIS-017","ruolo":"Secondario","peso":4,"macro_area":"Velocità","obiettivo_fisico":"Rapidità piedi","motivazione":"La qualità dei piccoli appoggi condiziona la rapidità di ritorno in guardia.","attivo":true},{"exercise_code":"GK-PRA-037","physical_objective_code":"FIS-023","ruolo":"Secondario","peso":4,"macro_area":"Reattività","obiettivo_fisico":"Reazione multidirezionale","motivazione":"La sequenza richiede reazioni rapide verso soluzioni o direzioni successive.","attivo":true},{"exercise_code":"GK-PRA-038","physical_objective_code":"FIS-019","ruolo":"Principale","peso":5,"macro_area":"Agilità","obiettivo_fisico":"Arresto e ripartenza","motivazione":"La sequenza richiede arresto, recupero posturale e nuova accelerazione.","attivo":true},{"exercise_code":"GK-PRA-038","physical_objective_code":"FIS-013","ruolo":"Secondario","peso":4,"macro_area":"Esplosività","obiettivo_fisico":"Spinta laterale","motivazione":"Il gesto richiede una spinta esplosiva sul piano laterale.","attivo":true},{"exercise_code":"GK-PRA-038","physical_objective_code":"FIS-014","ruolo":"Secondario","peso":4,"macro_area":"Esplosività","obiettivo_fisico":"Esplosività monopodalica","motivazione":"La spinta del tuffo è prevalentemente monopodalica.","attivo":true},{"exercise_code":"GK-PRA-038","physical_objective_code":"FIS-027","ruolo":"Secondario","peso":4,"macro_area":"Pliometria","obiettivo_fisico":"Pliometria laterale","motivazione":"La componente laterale richiede produzione reattiva di forza e controllo del contatto.","attivo":true},{"exercise_code":"GK-PRA-038","physical_objective_code":"FIS-017","ruolo":"Secondario","peso":4,"macro_area":"Velocità","obiettivo_fisico":"Rapidità piedi","motivazione":"La qualità dei piccoli appoggi condiziona la rapidità di ritorno in guardia.","attivo":true},{"exercise_code":"GK-PRA-039","physical_objective_code":"FIS-019","ruolo":"Principale","peso":5,"macro_area":"Agilità","obiettivo_fisico":"Arresto e ripartenza","motivazione":"La sequenza richiede arresto, recupero posturale e nuova accelerazione.","attivo":true},{"exercise_code":"GK-PRA-039","physical_objective_code":"FIS-012","ruolo":"Secondario","peso":4,"macro_area":"Esplosività","obiettivo_fisico":"Spinta orizzontale","motivazione":"Il movimento richiede produzione rapida di forza sul piano orizzontale/in avanti.","attivo":true},{"exercise_code":"GK-PRA-039","physical_objective_code":"FIS-020","ruolo":"Secondario","peso":4,"macro_area":"Agilità","obiettivo_fisico":"Spostamenti multidirezionali","motivazione":"Il compito richiede spostamento e riallineamento in direzioni differenti.","attivo":true},{"exercise_code":"GK-PRA-039","physical_objective_code":"FIS-017","ruolo":"Secondario","peso":4,"macro_area":"Velocità","obiettivo_fisico":"Rapidità piedi","motivazione":"La qualità dei piccoli appoggi condiziona la rapidità di ritorno in guardia.","attivo":true},{"exercise_code":"GK-PRA-039","physical_objective_code":"FIS-023","ruolo":"Secondario","peso":4,"macro_area":"Reattività","obiettivo_fisico":"Reazione multidirezionale","motivazione":"La sequenza richiede reazioni rapide verso soluzioni o direzioni successive.","attivo":true},{"exercise_code":"GK-PRA-040","physical_objective_code":"FIS-019","ruolo":"Principale","peso":5,"macro_area":"Agilità","obiettivo_fisico":"Arresto e ripartenza","motivazione":"La sequenza richiede arresto, recupero posturale e nuova accelerazione.","attivo":true},{"exercise_code":"GK-PRA-040","physical_objective_code":"FIS-011","ruolo":"Secondario","peso":4,"macro_area":"Esplosività","obiettivo_fisico":"Spinta verticale","motivazione":"La componente dominante è la produzione rapida di forza verticale per elevazione e presa alta.","attivo":true},{"exercise_code":"GK-PRA-040","physical_objective_code":"FIS-025","ruolo":"Secondario","peso":4,"macro_area":"Pliometria","obiettivo_fisico":"Pliometria verticale","motivazione":"Il gesto utilizza il ciclo stiramento-accorciamento in direzione verticale.","attivo":true},{"exercise_code":"GK-PRA-040","physical_objective_code":"FIS-017","ruolo":"Secondario","peso":4,"macro_area":"Velocità","obiettivo_fisico":"Rapidità piedi","motivazione":"La qualità dei piccoli appoggi condiziona la rapidità di ritorno in guardia.","attivo":true},{"exercise_code":"GK-PRA-040","physical_objective_code":"FIS-023","ruolo":"Secondario","peso":4,"macro_area":"Reattività","obiettivo_fisico":"Reazione multidirezionale","motivazione":"La sequenza richiede reazioni rapide verso soluzioni o direzioni successive.","attivo":true}]$mapping_json$::jsonb;
  missing_exercises text;
  missing_objectives text;
  mismatched_objectives text;
  multiple_primary_exercises text;
  duplicate_pairs text;
begin
  select string_agg(m.exercise_code, ', ' order by m.exercise_code)
  into missing_exercises
  from (select distinct exercise_code from jsonb_to_recordset(mapping_data) as source(exercise_code text, physical_objective_code text, ruolo text, peso integer, macro_area text, obiettivo_fisico text, motivazione text, attivo boolean)) m
  left join public.exercises e on e.codice = m.exercise_code
  where e.id is null;

  select string_agg(m.physical_objective_code, ', ' order by m.physical_objective_code)
  into missing_objectives
  from (select distinct physical_objective_code from jsonb_to_recordset(mapping_data) as source(exercise_code text, physical_objective_code text, ruolo text, peso integer, macro_area text, obiettivo_fisico text, motivazione text, attivo boolean)) m
  left join public.physical_objectives p on p.codice = m.physical_objective_code
  where p.id is null;

  select string_agg(distinct m.physical_objective_code, ', ' order by m.physical_objective_code)
  into mismatched_objectives
  from jsonb_to_recordset(mapping_data) as m(exercise_code text, physical_objective_code text, ruolo text, peso integer, macro_area text, obiettivo_fisico text, motivazione text, attivo boolean)
  join public.physical_objectives p on p.codice = m.physical_objective_code
  where p.macro_area <> m.macro_area or p.obiettivo_fisico <> m.obiettivo_fisico;

  select string_agg(x.exercise_code, ', ' order by x.exercise_code)
  into multiple_primary_exercises
  from (
    select exercise_code
    from jsonb_to_recordset(mapping_data) as source(exercise_code text, physical_objective_code text, ruolo text, peso integer, macro_area text, obiettivo_fisico text, motivazione text, attivo boolean)
    where ruolo = 'Principale'
    group by exercise_code
    having count(*) > 1
  ) x;

  select string_agg(x.exercise_code || ' / ' || x.physical_objective_code, ', ' order by x.exercise_code, x.physical_objective_code)
  into duplicate_pairs
  from (
    select exercise_code, physical_objective_code
    from jsonb_to_recordset(mapping_data) as source(exercise_code text, physical_objective_code text, ruolo text, peso integer, macro_area text, obiettivo_fisico text, motivazione text, attivo boolean)
    group by exercise_code, physical_objective_code
    having count(*) > 1
  ) x;

  if missing_exercises is not null then
    raise exception 'Esercizi tecnici mancanti: %', missing_exercises;
  end if;
  if missing_objectives is not null then
    raise exception 'Obiettivi fisici mancanti: %', missing_objectives;
  end if;
  if mismatched_objectives is not null then
    raise exception 'Nome o macro-area FIS non coerenti: %', mismatched_objectives;
  end if;
  if multiple_primary_exercises is not null then
    raise exception 'Più obiettivi principali per: %', multiple_primary_exercises;
  end if;
  if duplicate_pairs is not null then
    raise exception 'Associazioni duplicate: %', duplicate_pairs;
  end if;

  update public.exercise_physical_objectives existing
  set ruolo = 'Secondario'
  from public.exercises exercise,
       public.physical_objectives current_objective,
       jsonb_to_recordset(mapping_data) as official_primary(exercise_code text, physical_objective_code text, ruolo text, peso integer, macro_area text, obiettivo_fisico text, motivazione text, attivo boolean)
  where existing.exercise_id = exercise.id
    and existing.physical_objective_id = current_objective.id
    and existing.ruolo = 'Principale'
    and official_primary.exercise_code = exercise.codice
    and official_primary.ruolo = 'Principale'
    and official_primary.physical_objective_code <> current_objective.codice;

  insert into public.exercise_physical_objectives as target (
    exercise_id, physical_objective_id, ruolo, peso, motivazione, attivo
  )
  select
    e.id,
    p.id,
    m.ruolo,
    m.peso,
    m.motivazione,
    m.attivo
  from jsonb_to_recordset(mapping_data) as m(exercise_code text, physical_objective_code text, ruolo text, peso integer, macro_area text, obiettivo_fisico text, motivazione text, attivo boolean)
  join public.exercises e on e.codice = m.exercise_code
  join public.physical_objectives p on p.codice = m.physical_objective_code
  on conflict (exercise_id, physical_objective_id) do update set
    ruolo = excluded.ruolo,
    peso = excluded.peso,
    motivazione = excluded.motivazione,
    attivo = excluded.attivo;
end
$mapping_import$;

create or replace function public.set_exercise_physical_objective(
  requested_exercise_id uuid,
  requested_physical_objective_id uuid,
  requested_role text,
  requested_weight integer,
  requested_reason text,
  requested_active boolean default true
)
returns public.exercise_physical_objectives
language plpgsql
security invoker
set search_path = public
as $$
declare
  saved_mapping public.exercise_physical_objectives;
begin
  if requested_role not in ('Principale', 'Secondario', 'Complementare') then
    raise exception 'Ruolo non valido: %', requested_role;
  end if;
  if requested_weight not between 1 and 5 then
    raise exception 'Peso non valido: %', requested_weight;
  end if;

  if requested_role = 'Principale' then
    update public.exercise_physical_objectives
    set ruolo = 'Secondario'
    where exercise_id = requested_exercise_id
      and ruolo = 'Principale'
      and physical_objective_id <> requested_physical_objective_id;
  end if;

  insert into public.exercise_physical_objectives (
    exercise_id, physical_objective_id, ruolo, peso, motivazione, attivo
  ) values (
    requested_exercise_id, requested_physical_objective_id, requested_role,
    requested_weight, nullif(trim(requested_reason), ''), requested_active
  )
  on conflict (exercise_id, physical_objective_id) do update set
    ruolo = excluded.ruolo,
    peso = excluded.peso,
    motivazione = excluded.motivazione,
    attivo = excluded.attivo
  returning * into saved_mapping;

  return saved_mapping;
end;
$$;

create or replace function public.get_exercises_by_physical_objective(
  requested_physical_objective_id uuid
)
returns table (
  mapping_id uuid,
  exercise_id uuid,
  physical_objective_id uuid,
  ruolo text,
  peso integer,
  motivazione text,
  codice text,
  nome text,
  category_id integer,
  subcategory_id integer,
  categoria text,
  sottocategoria text,
  fase text,
  difficolta smallint,
  portieri_min integer,
  portieri_max integer,
  materiale text
)
language sql
stable
security invoker
set search_path = public
as $$
  select
    mapping.id,
    exercise.id,
    mapping.physical_objective_id,
    mapping.ruolo,
    mapping.peso,
    mapping.motivazione,
    exercise.codice,
    exercise.nome,
    exercise.category_id,
    exercise.subcategory_id,
    exercise.categoria,
    exercise.sottocategoria,
    exercise.fase,
    exercise.difficolta,
    exercise.portieri_min,
    exercise.portieri_max,
    exercise.materiale
  from public.exercise_physical_objectives mapping
  join public.exercises exercise on exercise.id = mapping.exercise_id
  where mapping.physical_objective_id = requested_physical_objective_id
    and mapping.attivo = true
    and exercise.attivo = true
  order by mapping.peso desc, exercise.codice asc;
$$;

comment on table public.exercise_physical_objectives is 'Compatibilità molti-a-molti tra esercizi tecnici e obiettivi fisici.';
comment on column public.exercise_physical_objectives.peso is 'Compatibilità da 1 (marginale) a 5 (molto alta).';
comment on function public.get_exercises_by_physical_objective(uuid) is 'Restituisce gli esercizi tecnici compatibili ordinati per peso decrescente.';

commit;
